# cook your dish here
import sys
MOD=998244353
def allowed_mask(n,value,positions,reflected=False):
    full=(1<<value)-1
    result=full
    
    for position in positions:
        i=n+1-position if reflected else position
        
        half=(i-1)//2
        forced=i-n+value-1
        valid=0
        
        if forced==half:
            valid=(1<<(half+1))-1
        elif forced<half:
            valid=1<<half
            
        if value-i==(n-i)//2:
            valid|=full^((1<<(i-1))-1)
        result&=valid
    return result
def count_valid(a):
    n=len(a)
    
    positions=[[] for i in range(n+1)]
    for i,value in enumerate(a,1):
        positions[value].append(i)
        
    dp=[1]
    
    for value in range(1,n):
        left_mask=allowed_mask(n,value,positions[value])
        right_mask=allowed_mask(n,value,positions[value],reflected=True)
        left=format(left_mask,f"0{value}b")[::-1]
        right=format(right_mask,f"0{value}b")
        
        new_dp=[0]*(value+1)
        
        for used_left,ways in enumerate(dp):
            if left[used_left]=="1":
                new_dp[used_left+1]=(
                    new_dp[used_left+1]+ways
                )%MOD
                
            if right[used_left]=="1":
                new_dp[used_left]=(
                    new_dp[used_left]+ways
                )%MOD
        dp=new_dp
        if not any(dp):
            return 0
    final_mask=allowed_mask(n,n,positions[n])
    valid=format(final_mask,f"0{n}b")[::-1]
    
    answer=0
    for used_left,ways in enumerate(dp):
        if valid[used_left]=="1":
            answer=(answer+ways)%MOD
    return answer

def solve():
    data=iter(map(int,sys.stdin.buffer.read().split()))
    t=next(data)
    answers=[]
    
    for case in range(t):
        n=next(data)
        a=[next(data) for i in range(n)]
        answers.append(str(count_valid(a)))
    
    sys.stdout.write("\n".join(answers))
solve()
